mapper.select:
SELECT * FROM ( SELECT I.INQUIRY_CODE, IT.INQUIRY_TYPE_NAME, I.TITLE, CASE WHEN I.OPERATOR_CODE IS NOT NULL THEN CR.ACTIVITY_NAME ELSE M.NAME END AS WRITER_NAME, I.WRITER_TYPE, I.INQUIRY_DATE, CASE WHEN I.ANSWER IS NULL OR TRIM(I.ANSWER) IS NULL THEN '답변대기' ELSE '답변완료' END AS ANSWER_STATUS, ROW_NUMBER() OVER ( ORDER BY I.INQUIRY_DATE DESC, I.INQUIRY_CODE DESC ) AS RN FROM INQUIRY I JOIN INQUIRY_TYPE IT ON I.INQUIRY_TYPE_CODE = IT.INQUIRY_TYPE_CODE
WHERE 1 = 1
AND ( I.TITLE LIKE '%' || #{search.keyword} || '%' OR NVL(M.NAME, CR.ACTIVITY_NAME) LIKE '%' || #{search.keyword} || '%' )
AND I.INQUIRY_TYPE_CODE = #{search.inquiryTypeCode}
AND (I.ANSWER IS NULL OR TRIM(I.ANSWER) IS NULL)
AND I.ANSWER IS NOT NULL AND TRIM(I.ANSWER) IS NOT NULL
) WHERE RN BETWEEN #{search.startRow} AND #{search.endRow}

mapper.update:
UPDATE INQUIRY
SET ANSWER = #{answer},
    ANSWER_DATE = SYSDATE

    , MANAGER_CODE = #{managerCode}

WHERE INQUIRY_CODE = #{inquiryCode}
